function isOptionLikeToken(token) {
  if (token === '--') {
    return true;
  }

  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  if (token[1] === ' ') {
    return false;
  }

  return !isNegativeNumberToken(token);
}

function isShortHelpToken(token) {
  return token.length > 1 && token[0] === '-' && token[1] === 'h' && token[0] !== token[1];
}

function isHelpToken(token) {
  return token === '--help' || isShortHelpToken(token);
}

export function parseCommandLine(argv) {
  for (const token of argv) {
    if (isHelpToken(token)) {
      return { kind: 'help' };
    }
  }

  let value = '';
  let hasValue = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }
      break;
    }

