import { formatError, HELP_TEXT } from './lib/cli/messages.mjs';
import { parseCommandLine } from './lib/cli/parser.mjs';
import { runReferenceYaml } from './lib/runtime/reference_yaml.mjs';

function main(argv) {
  const parsed = parseCommandLine(argv);

  if (parsed.kind === 'help') {
    process.stdout.write(HELP_TEXT);
    process.exitCode = 0;
    return;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(formatError(parsed.message));
    process.exitCode = 2;
    return;
  }

  const result = runReferenceYaml(parsed.value);

  if (result.error) {
    process.stderr.write(`${result.error.message}\n`);
    process.exitCode = 1;
    return;
  }

  if (result.status === null) {
    process.exitCode = 1;
    return;
  }

  process.exitCode = result.status;
}

main(process.argv.slice(2));

